'use strict';
const app = document.querySelector('#app');
const dialog = document.querySelector('#dialog');
const modalContent = document.querySelector('#dialog-content');
const icon = (name, alt = '') => `<img src="assets/${name}.svg" alt="${alt}">`;
const esc = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const money = value => new Intl.NumberFormat('ru-RU').format(value) + ' ₽';
const baseTrips = [
 {id:'spb',city:'Санкт-Петербург',date:'17–19 ноября',person:'Александр Букин',initials:'АБ',purpose:'Встреча с партнёрами',amount:32400,kind:'plane',bookings:'Авиа + отель',status:'Всё забронировано'},
 {id:'kazan',city:'Казань',date:'23–25 ноября',person:'Мария Волкова',initials:'МВ',purpose:'Конференция по продажам',amount:12800,kind:'train',bookings:'Ж/д билеты',status:'Нужен отель'},
 {id:'ekb',city:'Екатеринбург',date:'2–4 декабря',person:'Дмитрий Орлов',initials:'ДО',purpose:'Запуск нового проекта',amount:41600,kind:'plane',bookings:'Авиа + отель',status:'Всё забронировано'}
];
let drafts=[];
try { const saved=JSON.parse(localStorage.getItem('alfa-trip-drafts')||'[]'); if(Array.isArray(saved)) drafts=saved.filter(t=>t&&typeof t.id==='string'&&typeof t.city==='string'&&typeof t.person==='string'&&typeof t.date==='string'&&typeof t.purpose==='string').slice(0,50).map(t=>({...t,kind:'case',amount:0,status:'Черновик',bookings:'Без бронирований',initials:'ЧР'})); } catch {}
let bookingKind='plane',collapsed=false;
const trips=()=>[...baseTrips,...drafts];
const button=(label,action,style='',arrow='arrow')=>`<button type="button" class="button ${style}" data-action="${action}">${label}${icon(arrow)}</button>`;
function landing(){return `<div class="landing" data-node-id="30:218">
 <header class="public-header"><a class="brand" href="#/" aria-label="Альфа-Командировки — главная">${icon('logo')}<span>Альфа-Командировки</span></a><nav class="public-nav" aria-label="О сервисе"><button data-action="features">Возможности</button><button data-action="start">Как начать</button><button data-action="faq">Вопросы и ответы</button></nav></header>
 <main id="content" class="hero"><div class="hero-copy" data-node-id="30:239"><p class="eyebrow">Билеты, отели и документы — в одной командировке</p><h1 class="hero-title"><span class="hero-title-line"><span>Командировки,</span></span><span class="hero-title-line"><span>в которых</span></span><span class="hero-title-line"><span class="hero-title-accent">всё по делу</span></span></h1><div class="hero-actions"><a class="button primary" href="#/dashboard">Войти по Alfa ID ${icon('arrow-white')}</a></div><div class="become"><span>Пока нет счёта в Альфе?</span><button data-action="client">Стать клиентом</button></div></div><div class="hero-art"><div class="circle">${icon('ellipse')}</div><img class="travel-kit" src="assets/travel-kit.png" alt="Красный самолёт, серебристые поезд, чемодан и документы для деловой поездки"></div></main>
 <section class="benefits" aria-label="Возможности сервиса" data-node-id="33:634">${[['ruble','0 ₽ за обслуживание','Оплачивайте только билеты и отели'],['plane-benefit','Авиа, ж/д и отели','Бронируйте всё для деловой поездки'],['documents-benefit','Документы для бизнеса','Получайте отчётность для бухгалтерии']].map(([i,h,p])=>`<div class="benefit"><div class="icon-well">${icon(i)}</div><div><strong>${h}</strong><p>${p}</p></div></div>`).join('')}</section></div>`}
function tripCard(t){const attention=t.status==='Нужен отель';return `<article class="trip ${attention?'attention':''}"><div class="trip-top"><span>${esc(t.date)}</span><span class="badge ${attention||t.status==='Черновик'?'warning':''}">${esc(t.status)}</span></div><h3>${esc(t.city)}</h3><p class="trip-purpose">${esc(t.purpose)}</p><div class="traveller"><span class="initials">${esc(t.initials)}</span>${esc(t.person)}</div><div class="booking-summary">${icon(t.kind)}<span>${esc(t.bookings)}</span><strong>${money(t.amount)}</strong></div>${button(attention?'Подобрать отель':'Открыть поездку',attention?'hotel':'trip:'+t.id,'compact '+(attention?'soft-red':''),attention?'arrow-red':'arrow')}</article>`}
function chart(){return `<div><p class="chart-caption">Расходы, тыс. ₽ · *Ноябрь — по 14 число</p><div class="chart" role="img" aria-label="Расходы по месяцам: июнь 72, июль 101, август 56, сентябрь 109, октябрь 83,4, ноябрь по 14 число 64,8 тысячи рублей">${[['Июн','72',40],['Июл','101',56],['Авг','56',31],['Сен','109',60],['Окт','83,4',46],['Ноя*','64,8',36]].map(([m,v,h])=>`<div class="chart-column"><span>${v}</span><div class="bar" style="--bar:${h}px"></div><span>${m}</span></div>`).join('')}</div></div>`}
function dashboard(){return `<div class="dashboard ${collapsed?'sidebar-small':''}" data-node-id="38:299">
 <aside class="sidebar" aria-label="Основная навигация"><div class="side-brand"><a href="#/" aria-label="На главную сервиса">${icon('logo')}</a><button class="collapse" data-action="collapse" aria-label="${collapsed?'Развернуть':'Свернуть'} меню" aria-expanded="${!collapsed}">${icon('back')}</button></div><nav class="side-nav">${[['home','Главная','home'],['case','Командировки','trips'],['users','Сотрудники','employees'],['doc','Документы','documents'],['chart','Аналитика','analytics']].map(([i,t,a],n)=>`<button class="nav-item ${n===0?'active':''}" data-action="${a}" aria-label="${t}" ${n===0?'aria-current="page"':''}>${icon(i)}<span class="nav-label">${t}</span>${n===1||n===3?`<span class="nav-count">${n===1?trips().length:2}</span>`:''}</button>`).join('')}</nav><button class="support" data-action="support" aria-label="Помощь в поездках">${icon('chat')}<strong>Всегда на связи</strong><span>Помощь в поездках<br>24 часа, каждый день</span></button></aside>
 <header class="app-header"><form class="global-search" id="global-search">${icon('search')}<input name="query" aria-label="Поиск по кабинету" placeholder="Документ, командировка, задача" autocomplete="off"></form><button class="profile" data-action="profile"><span><strong>ИП Букин А.А.</strong><br><small>Руководитель</small></span><span class="avatar">АБ</span></button></header>
 <main class="workspace" id="content"><div class="page-heading"><div><h1>Командировки</h1><div class="priorities"><span class="muted">${trips().length} поездки впереди · 1 нужно завершить</span><button class="text-link red-text" data-action="documents">${icon('doc-red')}Собрать документы · 2 поездки ${icon('arrow-red-small')}</button></div></div>${button('Новая командировка','new-trip','primary new-trip','arrow-white')}</div>
 <section class="search-panel" aria-label="Поиск билетов и отелей"><div class="search-top"><div class="tabs" role="tablist" aria-label="Вид бронирования">${[['plane','Авиабилеты'],['train','Ж/д билеты'],['hotel','Отели']].map(([i,t])=>`<button type="button" class="tab" role="tab" id="tab-${i}" aria-controls="booking-form" aria-selected="${i===bookingKind}" tabindex="${i===bookingKind?0:-1}" data-kind="${i}">${icon(i)}${t}</button>`).join('')}</div><p class="search-note">После выбора добавьте заказ в новую или существующую командировку</p></div><form id="booking-form" class="booking-form" role="tabpanel" aria-labelledby="tab-${bookingKind}">${bookingFields()}</form><div class="repeat"><span>Повторить маршрут:</span><button data-action="repeat">Москва → Санкт-Петербург</button></div></section>
 <div class="content-grid"><section class="trips" data-node-id="38:444"><div class="section-title"><h2>Предстоящие поездки</h2><span class="badge warning">1 требует внимания</span><button class="text-link" data-action="trips">Все командировки</button></div><div class="trip-list">${baseTrips.map(tripCard).join('')}</div></section>
 <section class="subscription" data-node-id="38:556"><div class="row"><h2>Премиум+</h2><span class="badge">Активна</span><button class="text-link" data-action="subscription" aria-label="Подробнее о подписке">${icon('arrow')}</button></div><p class="muted">Общие лимиты организации · ноябрь</p><dl>${[['Бизнес-залы','Осталось 2 из 4 проходов'],['Трансферы','Осталась 1 из 2 поездок'],['Страховка команды','Подключена'],['Консьерж','Доступен 24/7']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><div class="subscription-footer"><p class="muted">Лимиты обновятся 1 декабря</p><button class="text-link" data-action="subscription">Условия подписки и покрытие страховки</button></div></section>
 <section class="analytics" data-node-id="38:589"><div class="analytics-top"><h2>Завершённые командировки</h2><small>1 июня — 14 ноября 2026</small></div><div class="analytics-body"><div class="metrics"><div class="metric"><span class="muted">Расходы компании</span><strong>486 200 ₽</strong><small>За выбранный период</small></div><div class="metric"><span class="muted">Поездки</span><strong>24</strong><small>8 сотрудников</small></div></div>${chart()}</div><div class="analytics-footer"><span>Документы готовы по 22 из 24 поездок</span><button class="text-link" data-action="analytics">Открыть аналитику</button></div></section>
 <section class="recommendation" data-node-id="38:630"><div class="row">${icon('pin')}<span>Казань · 23–25 ноября</span></div><h2>Отель для Марии Волковой</h2><p>Рядом с конференцией. С завтраком<br>и документами для бухгалтерии.</p><button type="button" class="button compact">Подобрать к поездке ${icon('arrow')}</button><img class="hotel-art" src="assets/hotel.png" alt="Серебристый отель с красным входом"></section></div></main></div>`}
function bookingFields(){const hotel=bookingKind==='hotel';return `<label class="field"><span>${hotel?'Город':'Откуда'}</span><input name="from" value="${hotel?'Казань':'Москва'}" required maxlength="80" autocomplete="off"></label><label class="field"><span>${hotel?'Отель или район':'Куда'}</span><input name="to" placeholder="${hotel?'Название или район':'Город или аэропорт'}" ${hotel?'':'required'} maxlength="80" autocomplete="off"></label><label class="field"><span>Даты</span><button type="button" class="text-link date-trigger" data-action="dates">${hotel?'Заезд — Выезд':'Туда — Обратно'}</button><input type="hidden" name="start"><input type="hidden" name="end"></label><label class="field"><span>${hotel?'Гости':'Пассажиры'}</span><select name="passengers" aria-label="Количество сотрудников"><option value="1">1 сотрудник${bookingKind==='plane'?', эконом':''}</option><option value="2">2 сотрудника</option><option value="3">3 сотрудника</option><option value="4">4 сотрудника</option></select></label><button class="button dark" type="submit">Найти ${icon('arrow-white')}</button>`}
function resizeArt(){const circle=document.querySelector('.circle');if(circle)circle.style.setProperty('--circle-scale',circle.clientWidth/739)}
function render(){dialog.close();app.innerHTML=location.hash.startsWith('#/dashboard')?dashboard():landing();resizeArt();document.title=location.hash.startsWith('#/dashboard')?'Командировки — Альфа':'Альфа-Командировки'}
function modal(title,body){modalContent.innerHTML=`<h2 id="dialog-title">${title}</h2>${body}`;if(!dialog.open)dialog.showModal()}
let toastTimer;function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('toast-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('toast-visible'),3500)}
function showTrips(query=''){const found=trips().filter(t=>(t.city+' '+t.person+' '+t.purpose+' '+t.status).toLocaleLowerCase('ru').includes(query.toLocaleLowerCase('ru')));modal(query?'Результаты поиска':'Все командировки',`${query?`<p class="muted">По запросу «${esc(query)}»</p>`:''}${found.length?found.map(t=>`<div class="detail-row"><div><strong>${esc(t.city)}</strong><small>${esc(t.date)} · ${esc(t.person)}</small><span>${esc(t.status)}</span></div>${button('Открыть','trip:'+t.id,'compact')}</div>`).join(''):'<p class="empty">Ничего не найдено. Попробуйте город или имя сотрудника.</p>'}${button('Новая командировка','new-trip','primary','arrow-white')}`)}
function newTrip(){modal('Новая командировка',`<p class="muted">Сначала сохраните поездку, затем добавьте билеты и отель.</p><form id="new-trip-form"><label class="field"><span>Куда едем</span><input name="city" required maxlength="80" placeholder="Город"></label><label class="field"><span>Сотрудник</span><select name="person">${baseTrips.map(t=>`<option>${t.person}</option>`).join('')}</select></label><div class="form-grid"><label class="field"><span>Начало поездки</span><input type="date" name="start" required></label><label class="field"><span>Окончание поездки</span><input type="date" name="end" required></label></div><label class="field"><span>Цель поездки</span><input name="purpose" required maxlength="120" placeholder="Например, встреча с партнёрами"></label><p class="form-error" role="alert"></p><div class="demo-note">Демонстрационный черновик сохранится только в этом браузере. Бронирования и оплаты не выполняются.</div><button class="button primary" type="submit">Сохранить черновик ${icon('arrow-white')}</button></form>`)}
function chooseHotel(){bookingKind='hotel';if(!location.hash.startsWith('#/dashboard'))location.hash='#/dashboard';else render();const f=document.querySelector('#booking-form');if(f){f.elements.from.value='Казань';f.elements.start.value='2026-11-23';f.elements.end.value='2026-11-25';f.querySelector('.date-trigger').textContent='23 ноя — 25 ноя';f.elements.to.value='Рядом с конференцией';f.scrollIntoView({behavior:'smooth',block:'center'});f.elements.to.focus()}toast('Поиск отеля для поездки Марии Волковой')}
function handleAction(action){
 if(action.startsWith('trip:')){const t=trips().find(t=>t.id===action.slice(5));if(!t)return;modal(esc(t.city),`<p>${esc(t.date)} · ${esc(t.status)}</p><div class="detail-row"><span>Сотрудник</span><strong>${esc(t.person)}</strong></div><div class="detail-row"><span>Цель поездки</span><strong>${esc(t.purpose)}</strong></div><div class="detail-row"><span>${esc(t.bookings)}</span><strong>${money(t.amount)}</strong></div><div class="demo-note">Это демонстрационные данные. Реальные билеты и бронирования не оформляются.</div>${t.id==='kazan'?button('Подобрать отель','hotel','primary','arrow-white'):''}`);return}
 switch(action){
 case 'home':render();break;
 case 'collapse':collapsed=!collapsed;document.querySelector('.dashboard').classList.toggle('sidebar-small',collapsed);document.querySelector('.collapse').setAttribute('aria-expanded',String(!collapsed));document.querySelector('.collapse').setAttribute('aria-label',collapsed?'Развернуть меню':'Свернуть меню');break;
 case 'features':modal('Всё для деловой поездки','<div class="detail-row"><strong>Авиа, ж/д и отели</strong><span>Поиск и управление в одном кабинете</span></div><div class="detail-row"><strong>Поездки команды</strong><span>Сотрудники, даты и статусы</span></div><div class="detail-row"><strong>Документы</strong><span>Отчётность для бухгалтерии</span></div>'+button('Открыть демо-кабинет','enter','primary','arrow-white'));break;
 case 'start':modal('Как начать','<p>1. Войдите в кабинет.</p><p>2. Создайте командировку и выберите сотрудника.</p><p>3. Подберите билеты и отель для поездки.</p><div class="demo-note">В этой версии вход открывает демонстрационный кабинет без авторизации.</div>'+button('Перейти в кабинет','enter','primary','arrow-white'));break;
 case 'faq':modal('Вопросы и ответы','<details open><summary>Что можно попробовать?</summary><p>Поиск, просмотр поездок и создание локального черновика.</p></details><details><summary>Можно ли купить билет?</summary><p>Это демонстрационная версия. Она не подключена к поставщикам, банковским счетам и реальному бронированию.</p></details><details><summary>Где сохраняется черновик?</summary><p>Только в браузере на этом устройстве. При очистке данных браузера он будет удалён.</p></details>');break;
 case 'client':modal('Стать клиентом Альфы','<p>В этой демонстрационной версии открытие банковского счёта недоступно. Вы можете посмотреть кабинет и попробовать сценарий командировки.</p>'+button('Посмотреть кабинет','enter','primary','arrow-white'));break;
 case 'enter':dialog.close();location.hash='#/dashboard';break;
 case 'profile':modal('ИП Букин А.А.','<p>Роль: руководитель организации.</p><div class="demo-note">Вы находитесь в демонстрационном кабинете.</div>'+button('Вернуться на главную','logout'));break;
 case 'logout':location.hash='#/';break;
 case 'trips':showTrips();break;
 case 'new-trip':newTrip();break;
 case 'employees':modal('Сотрудники',baseTrips.map(t=>`<div class="detail-row"><div class="row"><span class="initials">${t.initials}</span><strong>${t.person}</strong></div><span>${t.city}</span></div>`).join(''));break;
 case 'documents':modal('Документы по поездкам','<p class="muted">Готовы по 22 из 24 завершённых поездок.</p><div class="detail-row"><div><strong>Поездка № 23</strong><small>Ожидается документ от отеля</small></div><span class="badge warning">Не готов</span></div><div class="detail-row"><div><strong>Поездка № 24</strong><small>Ожидается закрывающий документ</small></div><span class="badge warning">Не готов</span></div><div class="demo-note">В демонстрации нельзя запросить или скачать реальные документы.</div>');break;
 case 'analytics':modal('Аналитика командировок','<p class="muted">1 июня — 14 ноября 2026</p><div class="detail-row"><span>Расходы компании</span><strong>486 200 ₽</strong></div><div class="detail-row"><span>Завершено поездок</span><strong>24</strong></div><div class="detail-row"><span>Сотрудников</span><strong>8</strong></div>'+chart()+'<div class="demo-note">Данные из макета. Ноябрь показан по 14 число включительно.</div>');break;
 case 'subscription':modal('Премиум+','<p>Подписка активна. Общие лимиты организации на ноябрь:</p><div class="detail-row"><span>Бизнес-залы</span><strong>Осталось 2 из 4 проходов</strong></div><div class="detail-row"><span>Трансферы</span><strong>Осталась 1 из 2 поездок</strong></div><div class="detail-row"><span>Страховка команды</span><strong>Подключена</strong></div><div class="detail-row"><span>Консьерж</span><strong>Доступен 24/7</strong></div><div class="demo-note">Демонстрационные условия из макета. Реальные условия и покрытие определяются договором подписки.</div>');break;
 case 'support':modal('Помощь в поездках','<p>24 часа, каждый день.</p><div class="demo-note">Это демонстрация интерфейса. Чат с оператором здесь не подключён.</div><details><summary>Где посмотреть поездку?</summary><p>Нажмите «Открыть поездку» на карточке или «Все командировки».</p></details><details><summary>Как добавить командировку?</summary><p>Нажмите «Новая командировка», заполните форму и сохраните черновик.</p></details>');break;
 case 'hotel':dialog.close();chooseHotel();break;
 case 'repeat':setKind('plane');document.querySelector('[name=to]').value='Санкт-Петербург';document.querySelector('[name=to]').focus();toast('Маршрут заполнен. Выберите даты поездки.');break;
 case 'dates':{const f=document.querySelector('#booking-form');modal('Даты поездки',`<form id="dates-form"><div class="form-grid"><label class="field"><span>${bookingKind==='hotel'?'Заезд':'Туда'}</span><input type="date" name="start" required value="${f.elements.start.value}"></label><label class="field"><span>${bookingKind==='hotel'?'Выезд':'Обратно'}</span><input type="date" name="end" required value="${f.elements.end.value}"></label></div><p class="form-error" role="alert"></p><button class="button primary" type="submit">Применить</button></form>`);break;}
 }
}
function setKind(kind){bookingKind=kind;document.querySelectorAll('[data-kind]').forEach(el=>{el.setAttribute('aria-selected',String(el.dataset.kind===kind));el.tabIndex=el.dataset.kind===kind?0:-1});const f=document.querySelector('#booking-form');f.innerHTML=bookingFields();f.setAttribute('aria-labelledby','tab-'+kind)}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(target)handleAction(target.dataset.action);const tab=event.target.closest('[data-kind]');if(tab)setKind(tab.dataset.kind)});
document.addEventListener('keydown',event=>{if(!event.target.matches('[role=tab]')||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const kinds=['plane','train','hotel'];const idx=kinds.indexOf(bookingKind);const next=event.key==='Home'?0:event.key==='End'?2:(idx+(event.key==='ArrowRight'?1:2))%3;setKind(kinds[next]);document.querySelector('#tab-'+kinds[next]).focus()});
document.addEventListener('submit',event=>{const f=event.target;event.preventDefault();const data=new FormData(f);
 if(f.id==='global-search'){const q=String(data.get('query')).trim();if(/документ/i.test(q))handleAction('documents');else showTrips(q);return}
 if(['dates-form','new-trip-form'].includes(f.id)){const start=String(data.get('start')),end=String(data.get('end'));if(end<start){f.querySelector('.form-error').textContent='Дата окончания должна быть не раньше даты начала.';return}if(f.id==='dates-form'){const booking=document.querySelector('#booking-form');booking.elements.start.value=start;booking.elements.end.value=end;const fmt=d=>new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'});booking.querySelector('.date-trigger').textContent=fmt(start)+' — '+fmt(end);dialog.close();return}
 const city=String(data.get('city')).trim(),purpose=String(data.get('purpose')).trim();if(!city||!purpose){f.querySelector('.form-error').textContent='Укажите город и цель поездки.';return}const dateFmt=d=>new Date(d+'T12:00:00').toLocaleDateString('ru-RU');const t={id:'draft-'+crypto.randomUUID(),city,purpose,person:String(data.get('person')),date:dateFmt(start)+' — '+dateFmt(end),initials:'ЧР',kind:'case',amount:0,status:'Черновик',bookings:'Без бронирований'};drafts.push(t);let stored=true;try{localStorage.setItem('alfa-trip-drafts',JSON.stringify(drafts))}catch{stored=false}render();showTrips();toast(stored?'Черновик сохранён в этом браузере':'Черновик создан на эту сессию; хранилище браузера недоступно');return}
 if(f.id==='booking-form'){const from=String(data.get('from')).trim(),to=String(data.get('to')).trim();if(!from||(bookingKind!=='hotel'&&!to)){toast('Укажите город отправления и назначения.');return}if(bookingKind!=='hotel'&&from.toLocaleLowerCase('ru')===to.toLocaleLowerCase('ru')){toast('Города отправления и назначения должны отличаться.');return}if(!data.get('start')||!data.get('end')){handleAction('dates');return}modal('Параметры поиска',`<p><strong>${esc(from)}${bookingKind!=='hotel'?' → '+esc(to):to?' · '+esc(to):''}</strong></p><div class="detail-row"><span>Даты</span><strong>${esc(data.get('start'))} — ${esc(data.get('end'))}</strong></div><div class="detail-row"><span>Сотрудников</span><strong>${esc(data.get('passengers'))}</strong></div><div class="demo-note">Поиск сформирован. Для получения реальных предложений потребуется подключение сервиса бронирования. Демонстрация не показывает вымышленные цены и наличие.</div>`)}
});
document.querySelector('.close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});window.addEventListener('resize',resizeArt);render();
